// Status bar update
function setStatusBar(message, isSuccess = true) {
  const sb = document.querySelector("#statusbar #text") || document.getElementById("text");
  if (sb) {
    sb.innerText = message;
    sb.style.color = isSuccess ? "#0ce791" : "#f87171";
  }
}

// Clipboard helper with Dual Windows Clipboard
async function copyToClipboardAdvanced(convertedPua, ansiBytes, originalTelugu) {
  if (window.__TAURI__ && window.__TAURI__.core) {
    try {
      await window.__TAURI__.core.invoke("copy_to_clipboard_advanced", {
        text: ansiBytes,
        unicodeText: originalTelugu
      });
      return;
    } catch (err) {
      console.warn("Tauri clipboard invocation error:", err);
    }
  }
  // Standard browser clipboard fallback
  try {
    await navigator.clipboard.writeText(convertedPua);
  } catch (e) {}
}

// Core conversion runner using Native Rust Backend with JS fallback
async function doConvert() {
  const inputEl = document.querySelector(".input textarea");
  const outputEl = document.querySelector(".output textarea");
  if (!inputEl || !outputEl) return;

  const rawText = inputEl.value;
  if (!rawText || rawText.trim().length === 0) {
    setStatusBar("Please enter Telugu text to convert.", false);
    return;
  }

  let convertedPua = "";
  let ansiText = "";

  // 1. Prioritize native compiled Rust backend
  if (window.__TAURI__ && window.__TAURI__.core) {
    try {
      const res = await window.__TAURI__.core.invoke("convert_telugu", { text: rawText });
      convertedPua = res.pua_text;
      ansiText = res.ansi_text;
    } catch (err) {
      console.warn("Native Rust conversion error, falling back to client JS:", err);
      convertedPua = os(rawText);
      ansiText = cs(convertedPua);
    }
  } else {
    // Browser fallback
    convertedPua = os(rawText);
    ansiText = cs(convertedPua);
  }

  outputEl.value = convertedPua;
  outputEl.focus();
  outputEl.select();

  await copyToClipboardAdvanced(convertedPua, ansiText, rawText);
  setStatusBar("Text just copied to clipboard.");
}

// Window controls
function setupWindowControls() {
  const minBtn = document.getElementById("titlebar-minimize");
  const maxBtn = document.getElementById("titlebar-maximize");
  const closeBtn = document.getElementById("titlebar-close");

  const invoke = (cmd) => {
    if (window.__TAURI__ && window.__TAURI__.core) {
      window.__TAURI__.core.invoke(cmd).catch(err => console.warn(cmd, err));
    }
  };

  if (minBtn) minBtn.onclick = () => invoke("win_minimize");
  if (maxBtn) maxBtn.onclick = () => invoke("win_toggle_maximize");
  if (closeBtn) closeBtn.onclick = () => invoke("win_close");
}

// Keyboard Hook Toggle
function setupKeyboardHook() {
  const toggleBtn = document.getElementById("toggle_btn");
  if (!toggleBtn) return;

  let isHooked = false;

  toggleBtn.onclick = async () => {
    if (window.__TAURI__ && window.__TAURI__.core) {
      try {
        const state = await window.__TAURI__.core.invoke("toggle_keyboard");
        isHooked = state;
        toggleBtn.innerText = isHooked ? "Stop Keyboard Hook" : "Start Keyboard Hook";
        toggleBtn.style.background = isHooked ? "#ef4444" : "";
        setStatusBar(isHooked ? "System keyboard hook active." : "Keyboard hook stopped.");
      } catch (err) {
        console.warn("Keyboard hook toggle failed:", err);
      }
    } else {
      isHooked = !isHooked;
      toggleBtn.innerText = isHooked ? "Stop Keyboard Hook" : "Start Keyboard Hook";
      toggleBtn.style.background = isHooked ? "#ef4444" : "";
      setStatusBar(isHooked ? "Simulated keyboard hook active." : "Keyboard hook stopped.");
    }
  };
}

// Navigation tabs
function setupNavigation() {
  const navItems = document.querySelectorAll(".nav-item");
  const pages = document.querySelectorAll(".main > .page-container");

  navItems.forEach(item => {
    item.addEventListener("click", () => {
      const targetId = item.id;
      navItems.forEach(n => n.classList.remove("selected"));
      item.classList.add("selected");

      pages.forEach(p => {
        if (p.id === targetId) {
          p.classList.remove("d-none");
          p.style.display = "block";
        } else {
          p.classList.add("d-none");
          p.style.display = "none";
        }
      });
    });
  });
}

// Initialize OpenTelugu
function initOpenTelugu() {
  // Bind convert button
  const convertBtn = document.getElementById("convertBtn") || document.querySelector(".actions > .convert > button");
  if (convertBtn) {
    convertBtn.onclick = (e) => {
      e.preventDefault();
      doConvert();
    };
  }

  // Bind keydown events
  const inputEl = document.querySelector(".input textarea");
  if (inputEl) {
    inputEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        doConvert();
      }
    });
  }

  const outputEl = document.querySelector(".output textarea");
  if (outputEl) {
    outputEl.addEventListener("keydown", (e) => {
      if (e.ctrlKey && (e.key === "c" || e.key === "C")) {
        const sel = outputEl.value.substring(outputEl.selectionStart, outputEl.selectionEnd) || outputEl.value;
        const ansi = cs(sel);
        copyToClipboardAdvanced(sel, ansi, sel);
        setStatusBar("Text copied to clipboard.");
      }
    });
  }

  setupNavigation();
  setupWindowControls();
  setupKeyboardHook();
  setStatusBar("OpenTelugu Engine Ready.");
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", initOpenTelugu);
} else {
  initOpenTelugu();
}
